/* ===== V103: تنبيه نقص المخزن ===== */
const LOW_ITEMS=[
  ['fishbox','كارتون بوكس','bLeft',20],['stubs','علب صلصة البوكس','stLeft',20],
  ['mabooj','معبوج جاهز','mLeft',10],['torshi','طرشي جاهز','tLeft',10],['rice','تمن جاهز','rLeft',10],['tamur','تمر جاهز','tmLeft',10],
  ['mtubs','علب معبوج فارغة','mtLeft',20],['ttubs','علب طرشي فارغة','ttLeft',20],['rtubs','علب تمن فارغة','rtLeft',20],['tamtubs','علب تمر فارغة','tmtLeft',20]
];
if(!settings.low||typeof settings.low!=='object') settings.low={on:true,min:{},ack:{}};
if(!settings.low.min) settings.low.min={}; if(!settings.low.ack) settings.low.ack={};
LOW_ITEMS.forEach(([k,,,d])=>{ if(settings.low.min[k]===undefined) settings.low.min[k]=d });
function lowLeftNow(){
  ['storeCalc','torshiCalc','riceCalc','tamurCalc','boxCalc','tubsCalc'].forEach(f=>{ try{ window[f]&&window[f]() }catch(e){} });
  const r={};
  LOW_ITEMS.forEach(([k,,id])=>{ const e=document.getElementById(id); r[k]=e?(parseInt(String(e.textContent).replace(/[^\d]/g,''))||0):null });
  return r;
}
function lowShow(list,test){
  let ov=document.getElementById('lowOv');
  if(!ov){ ov=document.createElement('div'); ov.id='lowOv'; ov.className='al-ov low-ov'; document.body.appendChild(ov); }
  ov.innerHTML=`<div class="al-box" role="alertdialog" aria-modal="true" aria-labelledby="lowT">
    <div class="al-t" id="lowT">${test?'تجربة تنبيه المخزن':'المخزن دا يخلص'}</div>
    <div class="al-list">${test?'<div class="al-row">هيج يطلع لما تنقص مادة عن الحد. اضغط تم.</div>':list.map(x=>`<div class="al-row"><b>${esc(x.name)}</b>: باقي ${fmt(x.left)}<span>الحد ${fmt(x.min)} — اشتري أو جهز</span></div>`).join('')}</div>
    <button class="al-off" id="lowOff">تم، شفتها</button></div>`;
  ov.querySelector('#lowOff').addEventListener('click',()=>{
    if(!test){ list.forEach(x=>{ settings.low.ack[x.k]=1 }); saveAll() }
    ov.remove();
    if(!document.getElementById('alarmOv')&&!document.getElementById('waOv')) alStop();
  });
  if(!alOn) alStart();
}
function lowCheck(){
  if(!settings.low||settings.low.on===false) return;
  const left=lowLeftNow(), list=[]; let ch=false;
  LOW_ITEMS.forEach(([k,name])=>{
    const v=left[k], min=+settings.low.min[k]||0; if(v===null||!min) return;
    if(v<min){ if(!settings.low.ack[k]) list.push({k,name,left:v,min}) }
    else if(settings.low.ack[k]){ delete settings.low.ack[k]; ch=true }   /* انضاف مخزون: يرجع ينبه من ينقص مرة ثانية */
  });
  if(ch) saveAll();
  const ov=document.getElementById('lowOv');
  if(list.length&&!ov) lowShow(list,false);
  lowBadge(left);
}
function lowBadge(left){
  const b=document.querySelector('.tab[data-page="store"]'); if(!b) return;
  left=left||lowLeftNow();
  const n=LOW_ITEMS.filter(([k])=>left[k]!==null&&(+settings.low.min[k]||0)&&left[k]<(+settings.low.min[k]||0)).length;
  let s=b.querySelector('.low-badge'); if(!s){ s=document.createElement('span'); s.className='low-badge'; b.appendChild(s) }
  s.textContent=n?n:''; s.hidden=!n||settings.low.on===false; s.setAttribute('aria-label',n?n+' مواد ناقصة':'');
}
function lowRender(){
  const box=document.getElementById('lowList'); if(!box) return;
  const left=lowLeftNow();
  document.getElementById('lowOn').checked=settings.low.on!==false;
  box.innerHTML=LOW_ITEMS.map(([k,name])=>{ const v=left[k], m=+settings.low.min[k]||0, bad=v!==null&&m&&v<m;
    return `<label class="low-row ${bad?'bad':''}"><span>${name}<small>باقي ${v===null?'—':fmt(v)}</small></span><input type="number" inputmode="numeric" min="0" data-k="${k}" value="${m}" aria-label="حد ${name}"></label>` }).join('');
}
document.getElementById('lowList').addEventListener('change',e=>{
  const k=e.target.dataset.k; if(!k) return;
  settings.low.min[k]=Math.max(0,+e.target.value||0); delete settings.low.ack[k]; saveAll(); lowRender(); toast('انحفظ الحد'); lowCheck();
});
document.getElementById('lowOn').addEventListener('change',e=>{ settings.low.on=e.target.checked; saveAll(); lowBadge(); toast(e.target.checked?'التنبيه شغال':'التنبيه طافي') });
document.getElementById('lowTestBtn').addEventListener('click',()=>{ alUnlock(); lowShow([],true) });
setInterval(lowCheck,60000); setTimeout(lowCheck,4000);
document.querySelector('.tab[data-page="settings"]').addEventListener('click',()=>setTimeout(lowRender,50));
document.querySelector('.tab[data-page="store"]').addEventListener('click',()=>setTimeout(()=>lowBadge(),100));
lowRender();
    if(!document.getElementById('alarmOv')&&!document.getElementById('lowOv')) alStop();
  setTimeout(()=>{ try{ lowCheck() }catch(e){} },300);
const SAFI_VER='V103';
    <div class="card" id="lowCard">
      <h3>تنبيه نقص المخزن</h3>
      <p class="note" style="margin-bottom:10px">إذا مادة نزلت تحت الحد، يطلع تنبيه بصوت ويبقى لحد ما أحد يضغط "تم". ما يرجع ينبه على نفس المادة إلا بعد ما ينضاف إلها مخزون وترجع تنقص.</p>
      <label class="low-on"><input type="checkbox" id="lowOn"> التنبيه شغال</label>
      <div class="low-list" id="lowList"></div>
      <button class="btn-sm gold" id="lowTestBtn" style="width:100%;margin-top:12px">جرّب التنبيه</button>
    </div>
.al-ov.low-ov{background:rgba(180,110,0,.55);animation:lowp 1.2s infinite}
@keyframes lowp{50%{background:rgba(180,110,0,.85)}}
.low-ov .al-box{border-color:#F5A623}
.low-ov .al-t{color:#F5A623}
.low-ov .al-off{background:#F5A623}
@media(prefers-reduced-motion:reduce){.al-ov.low-ov{animation:none}}
.low-on{display:flex;align-items:center;gap:8px;margin-bottom:10px;cursor:pointer}
.low-on input{width:20px;height:20px;accent-color:#F5A623}
.low-list{display:grid;gap:6px}
.low-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;border:1px solid var(--line);border-radius:10px}
.low-row span{display:flex;flex-direction:column;font-size:15px}
.low-row small{font-size:12.5px;color:var(--mute,#9296A0)}
.low-row.bad{border-color:#F5A623}
.low-row.bad small{color:#F5A623}
.low-row input{width:90px;min-height:40px;text-align:center}
.low-badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;margin-inline-start:6px;border-radius:9px;background:#F5A623;color:#111;font-size:11px;font-weight:800}
